import { chromium } from "playwright-core";
import { createServer } from "vite";
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const SHOTS = path.join(ROOT, "screenshots");
const PORT = 5181;
const BASE_URL = `http://127.0.0.1:${PORT}/`;
const EXPECTED_AGENTS = ["chief", "scan", "vet", "social", "size", "fills", "risk", "crawler"];
const VIEWPORTS = [
  { name: "dashboard-1440", width: 1440, height: 1000, columns: 4 },
  { name: "dashboard-1024", width: 1024, height: 900, columns: 2 },
  { name: "dashboard-390", width: 390, height: 844, columns: 1 },
];

const chromeCandidates = [
  process.env.CHROME_PATH,
  "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
  "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
  "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
].filter(Boolean);
const executablePath = chromeCandidates.find((candidate) => fs.existsSync(candidate));

if (!executablePath) {
  throw new Error("No Chrome/Edge executable found. Set CHROME_PATH to run the screenshot verification.");
}

fs.mkdirSync(SHOTS, { recursive: true });

const report = {
  generatedAt: new Date().toISOString(),
  browser: executablePath,
  viewports: [],
  interactions: {},
};

function fail(message) {
  throw new Error(message);
}

async function waitForReady(page) {
  await page.waitForSelector('[data-testid="agent-card"]', { timeout: 20_000 });
  await page.evaluate(async () => {
    await document.fonts.ready;
  });
  await page.waitForTimeout(1400);
}

async function inspectViewport(page, viewport) {
  return page.evaluate((expectedColumns) => {
    const cards = Array.from(document.querySelectorAll('[data-testid="agent-card"]'));
    const grid = document.querySelector(".agent-grid");
    const room = document.querySelector('[data-testid="pixel-room"]');
    const roomSvg = room ? room.querySelector(".room-svg") : null;
    const roomBox = roomSvg ? roomSvg.getBoundingClientRect() : null;
    const equityLine = document.querySelector(".equity-line--core");
    const clientWidth = document.documentElement.clientWidth;
    const overflowing = Array.from(document.querySelectorAll("body *"))
      .filter((element) => {
        const style = getComputedStyle(element);
        if (style.display === "none" || style.visibility === "hidden" || style.position === "fixed") return false;
        if (element.closest(".room-viewport")) return false;
        const rect = element.getBoundingClientRect();
        return rect.width > 0 && (rect.right > clientWidth + 1 || rect.left < -1);
      })
      .slice(0, 8)
      .map((element) => `${element.tagName.toLowerCase()}.${String(element.className).split(" ").slice(0, 2).join(".")}`);

    return {
      cards: cards.length,
      agents: cards.map((card) => card.getAttribute("data-agent")),
      columns: grid ? getComputedStyle(grid).gridTemplateColumns.split(" ").filter(Boolean).length : 0,
      expectedColumns,
      roomWidth: roomBox ? Math.round(roomBox.width) : 0,
      roomHeight: roomBox ? Math.round(roomBox.height) : 0,
      candleBodies: document.querySelectorAll(".candle-body").length,
      stations: document.querySelectorAll(".station").length,
      thresholds: document.querySelectorAll(".threshold-list li").length,
      hasEquityPath: Boolean(equityLine && (equityLine.getAttribute("d") || "").length > 100),
      scrollWidth: document.documentElement.scrollWidth,
      bodyScrollWidth: document.body.scrollWidth,
      clientWidth,
      innerWidth: window.innerWidth,
      overflowing,
      title: document.title,
      h1: document.querySelector(".brand-copy h1")?.textContent?.replace(/\s+/g, " ").trim() ?? "",
    };
  }, viewport.columns);
}

async function validateMetrics(metrics, viewport, errors, responseStatus) {
  if (responseStatus && responseStatus >= 400) fail(`HTTP ${responseStatus} at ${viewport.width}px`);
  if (errors.length) fail(`Browser errors at ${viewport.width}px: ${errors.join(" | ")}`);
  if (metrics.cards !== 8) fail(`Expected 8 agent cards at ${viewport.width}px, found ${metrics.cards}`);
  if (JSON.stringify(metrics.agents) !== JSON.stringify(EXPECTED_AGENTS)) {
    fail(`Unexpected agent ids at ${viewport.width}px: ${metrics.agents.join(", ")}`);
  }
  if (metrics.columns !== viewport.columns) {
    fail(`Expected ${viewport.columns} agent columns at ${viewport.width}px, found ${metrics.columns}`);
  }
  if (metrics.roomWidth < 300 || metrics.roomHeight < 180) {
    fail(`Pixel room is too small at ${viewport.width}px (${metrics.roomWidth}x${metrics.roomHeight})`);
  }
  if (metrics.candleBodies < 20) fail(`Candle chart did not render at ${viewport.width}px`);
  if (metrics.stations < 6) fail(`Pixel room stations missing at ${viewport.width}px`);
  if (metrics.thresholds !== 8) fail(`Threshold table incomplete at ${viewport.width}px`);
  if (!metrics.hasEquityPath) fail(`Equity chart path missing at ${viewport.width}px`);
  if (metrics.scrollWidth > metrics.clientWidth + 1 || metrics.bodyScrollWidth > metrics.clientWidth + 1) {
    fail(`Horizontal overflow at ${viewport.width}px: scrollWidth=${metrics.scrollWidth}, clientWidth=${metrics.clientWidth}`);
  }
  if (metrics.overflowing.length) {
    fail(`Elements overflow at ${viewport.width}px: ${metrics.overflowing.join(", ")}`);
  }
  if (!metrics.title.includes("GROKBOT") || !metrics.h1.includes("GROKBOT")) {
    fail(`Unexpected page title/brand at ${viewport.width}px`);
  }
}

async function runInteractions(browser) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = [];
  page.on("pageerror", (error) => errors.push(error.message));
  page.on("console", (message) => {
    if (message.type() === "error") errors.push(message.text());
  });

  await page.goto(BASE_URL, { waitUntil: "domcontentloaded" });
  await waitForReady(page);

  await page.locator('[data-testid="pixel-room"]').screenshot({
    path: path.join(SHOTS, "pixel-room-1440.png"),
  });

  const chart = page.locator('[data-testid="equity-chart"]');
  await chart.scrollIntoViewIfNeeded();
  const chartBox = await chart.boundingBox();
  if (!chartBox) fail("Equity chart has no layout box");
  await page.mouse.move(chartBox.x + chartBox.width * 0.62, chartBox.y + chartBox.height * 0.42);
  await page.waitForSelector(".chart-tooltip", { timeout: 3000 });
  const tooltip = (await page.locator(".chart-tooltip").innerText()).replace(/\s+/g, " ").trim();
  await page.locator(".equity-panel").screenshot({
    path: path.join(SHOTS, "equity-hover-1440.png"),
  });

  const readTick = async () => {
    const text = await page.locator(".section-meta").innerText();
    const match = text.match(/TICK\s+(\d+)/);
    return match ? Number(match[1]) : -1;
  };

  const beforeHold = await readTick();
  await page.getByRole("button", { name: "Pause simulation" }).click();
  await page.waitForSelector(".room-held-badge", { timeout: 3000 });
  const heldTick = await readTick();
  await page.waitForTimeout(2100);
  const heldTickAfterWait = await readTick();
  if (heldTickAfterWait !== heldTick) fail("Stream advanced while paused");

  await page.getByRole("button", { name: "Advance simulation one tick" }).click();
  await page.waitForTimeout(200);
  const steppedTick = await readTick();
  if (steppedTick <= heldTick) fail("STEP did not advance exactly one simulation tick");

  await page.getByRole("button", { name: "Resume simulation" }).click();
  await page.waitForTimeout(2100);
  const resumedTick = await readTick();
  if (resumedTick <= steppedTick) fail("Stream did not resume after RESUME");

  if (errors.length) fail(`Browser errors during interaction: ${errors.join(" | ")}`);

  await page.close();
  return {
    beforeHold,
    heldTick,
    heldTickAfterWait,
    steppedTick,
    resumedTick,
    tooltip,
    roomScreenshot: "screenshots/pixel-room-1440.png",
    hoverScreenshot: "screenshots/equity-hover-1440.png",
  };
}

let server;
let browser;
try {
  server = await createServer({
    root: ROOT,
    logLevel: "error",
    server: { port: PORT, strictPort: true },
  });
  await server.listen();

  browser = await chromium.launch({ executablePath, headless: true });
  console.log(`Chrome: ${executablePath}`);
  console.log(`Preview: ${BASE_URL}`);

  for (const viewport of VIEWPORTS) {
    const page = await browser.newPage({
      viewport: { width: viewport.width, height: viewport.height },
      deviceScaleFactor: 1,
    });
    const errors = [];
    page.on("pageerror", (error) => errors.push(error.message));
    page.on("console", (message) => {
      if (message.type() === "error") errors.push(message.text());
    });

    const response = await page.goto(BASE_URL, { waitUntil: "domcontentloaded" });
    await waitForReady(page);
    const metrics = await inspectViewport(page, viewport);
    await validateMetrics(metrics, viewport, errors, response ? response.status() : 0);

    const shotPath = path.join(SHOTS, `${viewport.name}.png`);
    await page.screenshot({ path: shotPath, fullPage: true });
    const size = fs.statSync(shotPath).size;
    if (size < 30_000) fail(`Screenshot suspiciously small at ${viewport.width}px (${size} bytes)`);

    const result = {
      viewport: `${viewport.width}x${viewport.height}`,
      columns: metrics.columns,
      room: `${metrics.roomWidth}x${metrics.roomHeight}`,
      cards: metrics.cards,
      candleBodies: metrics.candleBodies,
      scrollWidth: metrics.scrollWidth,
      clientWidth: metrics.clientWidth,
      screenshot: `screenshots/${viewport.name}.png`,
      screenshotBytes: size,
    };
    report.viewports.push(result);
    console.log(`PASS ${result.viewport}: ${result.columns} cols, room ${result.room}, no overflow, ${Math.round(size / 1024)} KB`);

    await page.close();
  }

  report.interactions = await runInteractions(browser);
  console.log(
    `PASS pause/resume: held tick ${report.interactions.heldTick}, stepped ${report.interactions.steppedTick}, resumed ${report.interactions.resumedTick}`,
  );
  console.log(`PASS chart hover: ${report.interactions.tooltip}`);

  fs.writeFileSync(path.join(SHOTS, "verification.json"), JSON.stringify(report, null, 2));
  console.log("Screenshots written to screenshots/");
} catch (error) {
  report.error = error instanceof Error ? error.message : String(error);
  fs.writeFileSync(path.join(SHOTS, "verification.json"), JSON.stringify(report, null, 2));
  console.error(`SCREENSHOT VERIFICATION FAILED: ${report.error}`);
  process.exitCode = 1;
} finally {
  if (browser) await browser.close().catch(() => {});
  if (server) await server.close().catch(() => {});
}
